import json, os, sys
sys.stdout.reconfigure(encoding="utf-8")
HERE = os.path.dirname(os.path.abspath(__file__))
R = json.load(open(os.path.join(HERE, "results_M.json"), encoding="utf-8"))
C, ROWS, M = R["common"], R["rows"], R["main"]
f4 = lambda v: f"{v:.4f}"
EX = {e["name"]: e for e in M["extras"]}
g = M["tilt_point"]; p = ROWS[16]
o = []
w = o.append
w("# Section 2. Path Planning (UST Frassati to Metro Industries)\n")
w("## Site Locations\n")
w("**Table 2. Site Information**\n")
w("| | Site A | Site B |\n|---|---|---|")
w("| Area | Saint Pier Giorgio Frassati Building, España Boulevard, Sampaloc, Manila | Metro Industries, 84 Ramon Delfin St, Marulas, Valenzuela, Metro Manila |")
w(f"| Map coordinates | {ROWS[0]['lat']} {ROWS[0]['lon']} | {ROWS[-1]['lat']} {ROWS[-1]['lon']} |")
w("| Location description | A 23-storey building, with a rooftop | Rooftop of the Metro Industries building, Marulas (5 storeys assumed from satellite and street imagery; to be confirmed on site) |")
w("| Height of building | 23 × 2.5 m = 57.5 m | 5 × 2.5 m = 12.5 m |")
w(f"| Ground elevation (Google Earth) | {ROWS[0]['ground']:.2f} m | {ROWS[-1]['ground']:.2f} m |")
w(f"| Distance between sites A and B | {f4(C['d_km'])} km | |")
w("| List of obstructions on the straight-line path | White mid-rise north of EDSA (P17, 4 floors assumed), LRT-1 viaduct on EDSA (about 12.5 m with a train, between P15 and P16), Maranatha/PMCC tower (9 floors, about 5 m east of the line near d1 = 1.667 km), commercial buildings near CAI Sports Center (P14), warehouses near Caloocan City Hall (P12 to P13), and the cemetery and residential blocks from P8 to P11 | |\n")
w(f"Discussion: Site A is on the rooftop of the 23-storey Saint Pier Giorgio Frassati Building, and Site B is on the rooftop of the Metro Industries building at 84 Ramon Delfin St, Marulas, Valenzuela. The straight-line distance between the sites is {f4(C['d_km'])} km. Building heights use 2.5 m per floor.\n")
w("![Figure 2.1](map_points_M.jpg)\n")
w("*Figure 2.1: Straight-line path and the 20 points (FRASSATI, M2 to M19, and Site B) in Google Earth. The view is rotated so the path runs left to right; north is toward the left.*\n")
w(f"Discussion: The 18 points between the sites start from an even spacing of D/19 = {C['d_m']/19:.2f} m. Each point was then moved by up to 30 m along the line so that it sits on the tallest roof nearby, as the guideline asks, so the actual spacing is uneven. The table uses each point's actual distance from Site A. The LRT EDSA pin marks where the line crosses the LRT-1 viaduct; it is checked separately below.\n")
w("![Figure 2.2](map_overlay_M.png)\n")
w(f"*Figure 2.2: Simulated azimuth patterns at both sites, each pointed at the other site, with the {f4(C['d_km'])} km distance*\n")
w("Discussion: Each antenna's main lobe is pointed at the other site, so the maximum directive gain lies along the path.\n")
w("Reflection question: The azimuth pattern is used for the overlay. Google Maps shows the horizontal plane, and the azimuth pattern is the cut in that same plane, so it shows how the beam is pointed from one site toward the other. The elevation pattern describes the vertical plane, which a flat map cannot show.\n")
w("## Path Profile\n")
w("![Figure 2.3](path_profile_M.png)\n")
w("*Figure 2.3: Path profile showing all 20 points, THE, the near-line structures, and the tilted line of sight*\n")
w(f"Discussion: The ground rises from about 2.5 m near UST to about 20 m around EDSA (P16 and P17), drops to {ROWS[18]['ground']:.2f} m at the Tullahan River (P19), and rises again to {ROWS[-1]['ground']:.2f} m at Site B. The dashed red line is the tilted line of sight from {f4(M['h_ant_a'])} m at Frassati to {f4(M['h_ant_b'])} m at Metro Industries. It stays at or above THE at every point and at both near-line structures. It just touches the THE of P17 and passes {EX['L']['the'] and [x for x in M['clearance'] if x['name']=='L'][0]['margin']:.2f} m above the THE of the LRT-1 viaduct.\n")
w("**Table 3. Path Profile: Elevation, Earth Bulge, and Fresnel Clearance**\n")
w("| Point | d1 (km) | d2 (km) | Ground (m) | Floors | h_elevation (m) | h_earth bulge (m) | 0.6F1 (m) | THE (m) |\n|---|---|---|---|---|---|---|---|---|")
for r in ROWS:
    w(f"| {r['n']} | {f4(r['d1'])} | {f4(r['d2'])} | {r['ground']:.2f} | {r['floors']} | {f4(r['elev'])} | {f4(r['bulge'])} | {f4(r['f60'])} | {f4(r['the'])} |")
w("\n(The Ground and Floors columns are extra, to show where h_elevation comes from; the group's template table has only d1, d2, h_elevation, h_earth bulge, 0.6F1, and THE.)\n")
w("**Point locations and what is on each point**\n")
w("| Point | Latitude | Longitude | What is there |\n|---|---|---|---|")
for r in ROWS:
    w(f"| {r['n']} | {r['lat']} | {r['lon']} | {r['desc']} |")
w("\n**Sample computation at the highest intermediate point (P17)**\n")
w(f"- h_elevation = {p['ground']:.2f} + {p['floors']}(2.5) = {f4(p['elev'])} m")
w(f"- h_earth bulge = d1·d2 / 12.75 = ({f4(p['d1'])})({f4(p['d2'])}) / 12.75 = {f4(p['bulge'])} m")
w(f"- F1 = 17.3√[d1·d2 / (f(d1 + d2))] = 17.3√[({f4(p['d1'])})({f4(p['d2'])}) / (10.59625 × {f4(C['d_km'])})] = {f4(p['f1'])} m")
w(f"- 0.6F1 = 0.6({f4(p['f1'])}) = {f4(p['f60'])} m")
w(f"- THE = {f4(p['elev'])} + {f4(p['bulge'])} + {f4(p['f60'])} = {f4(p['the'])} m\n")
w("**Near-line structure check**\n")
for k in ("M", "L"):
    e = EX[k]
    w(f"- {e['label']}: d1 = {f4(e['d1'])} km, THE = {e['ground']:.2f} + {e['floors']}(2.5) + {f4(e['bulge'])} + {f4(e['f60'])} = {f4(e['the'])} m")
w("\n## Antenna Towers\n")
w("**Table 4. Antenna Heights**\n")
w("| Parameter | Site A Tower | Site B Tower |\n|---|---|---|")
w(f"| h_antenna | {f4(M['h_ant_a'])} m | {f4(M['h_ant_b'])} m (tilted) |")
w(f"| h_elevation | {f4(ROWS[0]['elev'])} m | {f4(ROWS[-1]['elev'])} m |")
w(f"| h_tower | {f4(M['tower_a'])} m | {f4(M['tower_b'])} m |\n")
w("**Tilted antenna mounting (guideline Part 3, item 9)**\n")
w(f"With equal antenna heights, both antennas would sit at the maximum THE of {f4(M['hmin'])} m (P1), which needs a {f4(M['flat_tower_b'])} m tower at Site B. The antennas are instead mounted at an angle, keeping line of sight and clearance from every THE.\n")
w(f"- Site A antenna height: hA = THE at P1 = {f4(M['h_ant_a'])} m, so h_tower,A = {f4(M['h_ant_a'])} − {f4(ROWS[0]['elev'])} = {f4(M['tower_a'])} m")
w("- For each point, the straight line from Site A must stay at or above THE: hA − (hA − hB)(d1 / D) ≥ THE, so hB ≥ hA − (hA − THE)(D / d1).")
w(f"- The largest required hB is at {g['name']}: hB = {f4(M['h_ant_a'])} − ({f4(M['h_ant_a'])} − {f4(g['the'])})({f4(C['d_km'])} / {f4(g['d1'])}) = {f4(M['h_ant_b'])} m")
w(f"- h_tower,B = {f4(M['h_ant_b'])} − {f4(ROWS[-1]['elev'])} = {f4(M['tower_b'])} m")
w(f"- Tilt angle = tan⁻¹[(hA − hB) / D] = tan⁻¹[({f4(M['h_ant_a'])} − {f4(M['h_ant_b'])}) / {C['d_m']:.2f}] = {M['tilt_deg']:.4f}°, downward at Site A and upward at Site B\n")
w(f"Justification: the ANDREW VHLP6-11W/A antenna mount has a ±5° fine elevation adjustment, so a {M['tilt_deg']:.4f}° tilt is within its range. The tilt is also smaller than half of the antenna's vertical beamwidth (1° on the specification sheet, 0.9200° simulated), and each antenna is aimed directly at the other.\n")
w("**Table 4.1. Clearance of the tilted line of sight at all 20 points and the two near-line structures (M: Maranatha/PMCC tower, L: LRT-1 viaduct)**\n")
w("| Point | d1 (km) | THE (m) | Line of sight (m) | Clearance above THE (m) |\n|---|---|---|---|---|")
for x in M["clearance"]:
    w(f"| {x['name']} | {f4(x['d1'])} | {f4(x['the'])} | {f4(x['line'])} | {f4(x['margin'])} |")
w(f"\nDiscussion: Site A needs no added tower, only a rooftop mount on the Frassati Building. Site B needs a {f4(M['tower_b'])} m mast on the Metro Industries rooftop instead of a {f4(M['flat_tower_b'])} m tower. P17 sets the tilt because the line of sight just touches its THE; the LRT-1 viaduct is the next closest. Both heights are estimates (P17 at 4 floors, the viaduct with a train at 12.5 m), taken on the high side, so the real clearance should be larger.\n")
w("---\n")
w("## Numbers for Section 3 (not yet in the report)\n")
w("| Item | Value |\n|---|---|")
w(f"| Waveguide length A / B (tower + 3 m) | {f4(M['len_a'])} m / {f4(M['len_b'])} m |")
w(f"| Waveguide loss A / B | {f4(M['wg_a'])} dB / {f4(M['wg_b'])} dB |")
w(f"| Free-space loss | {f4(C['fsl'])} dB |")
w(f"| Total gain | {f4(M['g_total'])} dB |")
w(f"| RSL at amplifier output | {f4(M['rsl_out'])} dBm |")
w(f"| Receiver sensitivity | {f4(M['pth'])} dBm |")
w(f"| Fade margin | {f4(M['fm'])} dB |")
w(f"| Microwave system loss | {f4(M['micro_loss'])} dB |")
w(f"| Fiber loss (8.9 km road length carried over from the Fini route; recheck for Metro Industries) | {f4(M['fiber_loss'])} dB |")
open(os.path.join(r"C:\UST\TRANSMA PROJECT", "Section2_Metro_Industries.md"), "w", encoding="utf-8").write("\n".join(o) + "\n")
print("ok", len(o))
